  "headline": "Vincristine sulfate is not on FDA's shortage list as of 2026-10-21; supply traces to a registered plant with a VAI inspection in 2022 and a prior OAI in 2014",
  "headline_cites": ["D3", "E8", "E6", "E5"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include vincristine sulfate as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "The product label for NDC 61703030925 identifies Hospira Australia Pty Ltd (FEI 3001174929) as the registered manufacturing plant.",
      "cites": ["E8"]
    },
    {
      "text": "FDA inspected that plant on 2022-09-02 and classified the inspection VAI.",
      "cites": ["E6"]
    },
    {
      "text": "An earlier inspection ending 2014-03-04 was classified OAI and a Warning Letter was issued on 2014-09-26.",
      "cites": ["E5", "E7"]
    },
    {
      "text": "Corvale East holds 64 vials of the 1 mg/mL, 2 mL presentation at 3.1 vials per day, providing 20.4 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 67 vials at 2.9 vials per day, providing 23.3 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Check current allocation status with the supplier and monitor FDA communications for any future shortage posting.",
      "cites": ["D3"]
    }
  ]
}
